/* @lc app=leetcode id=990 lang=kotlin */ class Solution { fun find(p: IntArray, x: Int): Int = if (p[x] == x) x else find(p, p[x]).also { p[x] = it } fun equationsPossible(equations: Array<String>): Boolean = IntArray(26) { it }.let { p -> equations.filter { it[1] == '=' }.forEach { p[find(p, it[0] - 'a')] = find(p, it[3] - 'a') }.let { equations.filter { it[1] == '!' }.none { find(p, it[0] - 'a') == find(p, it[3] - 'a') } } } }